# Cartões e faturas

## O quê e por quê

Hoje um cartão de crédito é só uma conta com saldo negativo. Na vida real o que importa é a **fatura**: o ciclo entre dois fechamentos, a data de vencimento, o limite disponível e as compras parceladas, que se espalham por vários meses. Esta parte acrescenta isso sem mudar o modelo de transações: a fatura é calculada a partir das transações da conta do cartão, e as parcelas são transações comuns ligadas por um grupo.

Extensões ao modelo (esquema versão 2):

- Conta do tipo `cartao` ganha `cartao: { diaFechamento, diaVencimento, limite }`.
- Transação ganha `parcela?: { grupoId, numero, total }`.
- O estado ganha `pagamentosFatura`: `{ id, contaCartaoId, mesFatura, valor, data, contaOrigemId }`. Um pagamento move dinheiro entre contas e **não** é receita nem despesa.

Esta spec estende [categorias-e-transacoes](2026-10-01-categorias-e-transacoes.md), que deixava transações parceladas fora do escopo, e [contas](2026-10-01-contas.md). Regras: a fatura de `mesFatura` = M reúne as transações com data maior que o dia de fechamento de M−1 e até o dia de fechamento de M (inclusive). O vencimento é o `diaVencimento` do mês M se for maior que o dia de fechamento; caso contrário, do mês M+1.

## Critérios de aceitação

1. Ao criar ou editar uma conta do tipo cartão, o formulário pede dia de fechamento e dia de vencimento (inteiros de 1 a 28) e limite (maior que zero); valores inválidos são recusados junto ao campo. Contas de outros tipos não guardam esses dados.
2. A tela Cartões lista os cartões ativos e, sem nenhum, mostra estado vazio com link para Contas. Cartões sem configuração de ciclo pedem para configurá-la antes de mostrar a fatura.
3. A fatura de um mês mostra as transações do ciclo e o total, que é a soma exata delas; navegar entre meses troca a fatura sem alterar dados.
4. O vencimento da fatura é calculado pela regra acima, inclusive quando o vencimento cai no mês seguinte ao do fechamento e na virada do ano.
5. Cada fatura tem situação em texto: "Aberta" (hoje até o fechamento), "Fechada" (passou do fechamento e há saldo a pagar) ou "Paga" (pagamentos cobrem o total). A situação não depende só de cor.
6. Uma compra parcelada pede descrição, valor total, número de parcelas (2 a 48), data da primeira parcela e categoria de despesa, e cria uma transação de despesa por parcela na conta do cartão, uma em cada mês, no mesmo dia (limitado ao último dia do mês).
7. A soma das parcelas é exatamente o valor total em centavos: o resto da divisão vai para a primeira parcela. A descrição de cada parcela termina em "(k/n)".
8. Cada parcela cai na fatura correta de acordo com o ciclo do cartão, inclusive parcelas de datas próximas ao dia de fechamento.
9. Ao excluir uma parcela, o usuário escolhe entre excluir só aquela parcela ou todas as do mesmo grupo; a escolha se reflete nas faturas e nos saldos.
10. Pagar uma fatura exige valor maior que zero, data válida e uma conta de origem ativa que não seja cartão. O pagamento aumenta o saldo do cartão e reduz o da origem; não aparece nos totais de receitas e despesas do dashboard nem das transações.
11. Pagamentos parciais são aceitos; um pagamento maior que o restante da fatura é recusado. A fatura mostra total, pago e restante.
12. O limite mostra usado (dívida atual do cartão, nunca negativa), disponível (limite menos usado) e uma barra de progresso com texto; se o disponível for negativo, exibe "limite excedido".
13. Dados salvos na versão 1 do esquema carregam sem erro: a migração para a versão 2 acrescenta `pagamentosFatura` vazio e nenhuma conta ou transação existente muda.
14. Uma conta de cartão com pagamentos de fatura não pode ser excluída, assim como já ocorre com contas que têm transações.

## Fora do escopo

- Juros rotativos, multas e encargos por atraso.
- Parcelamento de fatura e cartões adicionais de titulares diferentes.
- Conciliação com o PDF ou o CSV da fatura do banco.
- Fatura em moeda estrangeira e pontos de fidelidade.
- Lembretes e notificações de vencimento (veja calendário financeiro, se vier a existir).
export type Centavos = number;
/** Data no formato AAAA-MM-DD. */
export type DataISO = string;
/** Mês no formato AAAA-MM. */
export type Mes = string;

export type TipoConta = 'corrente' | 'poupanca' | 'dinheiro' | 'cartao' | 'investimento';
export type TipoMovimento = 'receita' | 'despesa';

/** Ciclo e limite de um cartão de crédito. Dias de 1 a 28 para valerem em todos os meses. */
export interface CartaoConfig {
  diaFechamento: number;
  diaVencimento: number;
  limite: Centavos;
}

export interface Conta {
  id: string;
  nome: string;
  tipo: TipoConta;
  saldoInicial: Centavos;
  arquivada: boolean;
  criadaEm: number;
  /** Só para contas do tipo cartão. */
  cartao?: CartaoConfig;
}

export interface Categoria {
  id: string;
  nome: string;
  tipo: TipoMovimento;
  arquivada: boolean;
}

export interface Transacao {
  id: string;
  contaId: string;
  categoriaId: string;
  tipo: TipoMovimento;
  /** Sempre positivo; o sinal vem do tipo. */
  valor: Centavos;
  data: DataISO;
  descricao: string;
  criadaEm: number;
  importacaoId?: string;
  /** Etiquetas livres, normalizadas (minúsculas); ausente quando não há nenhuma. */
  tags?: string[];
  /** Presente em compras parceladas; as parcelas de uma compra compartilham o grupoId. */
  parcela?: { grupoId: string; numero: number; total: number };
}

export interface Orcamento {
  categoriaId: string;
  mes: Mes;
  limite: Centavos;
}

export interface Aporte {
  id: string;
  data: DataISO;
  /** Positivo para aporte, negativo para retirada. */
  valor: Centavos;
}

export type StatusMeta = 'ativa' | 'concluida' | 'arquivada';

export interface Meta {
  id: string;
  nome: string;
  valorAlvo: Centavos;
  prazo?: DataISO;
  aportes: Aporte[];
  status: StatusMeta;
  concluidaEm?: DataISO;
  criadaEm: number;
}

/** Valor mensal fixo considerado na projeção; não gera transações. */
export interface Recorrencia {
  id: string;
  descricao: string;
  tipo: TipoMovimento;
  valor: Centavos;
  categoriaId: string;
  ativa: boolean;
}

export type FormatoData = 'dd/mm/aaaa' | 'aaaa-mm-dd' | 'dd-mm-aaaa';

export interface MapeamentoCsv {
  colData: number;
  colDescricao: number;
  /** Coluna única com sinal. */
  colValor: number | null;
  colCredito: number | null;
  colDebito: number | null;
  formatoData: FormatoData;
  temCabecalho: boolean;
}

export interface Importacao {
  id: string;
  data: DataISO;
  contaId: string;
  transacaoIds: string[];
}

/** Pagamento de fatura: movimenta dinheiro entre contas e não é receita nem despesa. */
export interface PagamentoFatura {
  id: string;
  contaCartaoId: string;
  /** Mês de fechamento da fatura (AAAA-MM). */
  mesFatura: Mes;
  valor: Centavos;
  data: DataISO;
  contaOrigemId: string;
}

/** Lançamento agendado (conta a pagar ou a receber); só vira transação quando é pago. */
export interface Agendamento {
  id: string;
  descricao: string;
  tipo: TipoMovimento;
  valor: Centavos;
  vencimento: DataISO;
  categoriaId: string;
  contaId?: string;
  /** Presente nos lançamentos gerados por recorrência mensal. */
  serie?: { grupoId: string; numero: number; total: number };
  pagoEm?: DataISO;
  transacaoId?: string;
  criadoEm: number;
}

export type ModoPadrao = 'contem' | 'comeca' | 'igual';

/** Regra de categorização; a prioridade é a posição na lista `regras`. */
export interface RegraCategoria {
  id: string;
  padrao: string;
  modo: ModoPadrao;
  tipo: TipoMovimento;
  categoriaId: string;
  tags: string[];
  ativa: boolean;
}

export type ClasseAtivo = 'renda-fixa' | 'acoes' | 'fundos' | 'cripto' | 'outros';

export interface MovimentoAtivo {
  id: string;
  tipo: 'aporte' | 'resgate';
  data: DataISO;
  /** Sempre positivo; o sinal vem do tipo. */
  valor: Centavos;
}

/** Valor de mercado anotado para um ativo numa data. */
export interface MarcacaoAtivo {
  id: string;
  data: DataISO;
  valor: Centavos;
}

/** Ativo da carteira manual de investimentos; não gera transações nem mexe em saldos. */
export interface Ativo {
  id: string;
  nome: string;
  classe: ClasseAtivo;
  movimentos: MovimentoAtivo[];
  marcacoes: MarcacaoAtivo[];
  criadoEm: number;
}

export type TipoDivida = 'devo' | 'emprestei';
export type SistemaAmortizacao = 'price' | 'sac';

/** Pagamento de dívida; sem `parcela` é uma amortização extra. */
export interface PagamentoDivida {
  id: string;
  data: DataISO;
  valor: Centavos;
  parcela?: number;
}

/** Dívida ou empréstimo concedido; `taxaBp` é a taxa mensal em centésimos de ponto percentual (199 = 1,99%). */
export interface Divida {
  id: string;
  nome: string;
  tipo: TipoDivida;
  principal: Centavos;
  taxaBp: number;
  parcelas: number;
  primeiraParcela: DataISO;
  sistema: SistemaAmortizacao;
  pagamentos: PagamentoDivida[];
  criadaEm: number;
}

export interface AppState {
  schemaVersion: number;
  contas: Conta[];
  categorias: Categoria[];
  transacoes: Transacao[];
  orcamentos: Orcamento[];
  metas: Meta[];
  recorrencias: Recorrencia[];
  mapeamentosCsv: Record<string, MapeamentoCsv>;
  importacoes: Importacao[];
  pagamentosFatura: PagamentoFatura[];
  agenda: Agendamento[];
  regras: RegraCategoria[];
  investimentos: Ativo[];
  dividas: Divida[];
}

export type Resultado<T> = { ok: true; valor: T } | { ok: false; erro: string; campo?: string };

export const ok = <T>(valor: T): Resultado<T> => ({ ok: true, valor });
export const falha = (erro: string, campo?: string): Resultado<never> => ({ ok: false, erro, campo });
import { categoriasPadrao } from '../data/categoriasPadrao';
import { falha, ok, type AppState, type Resultado } from '../domain/types';

/** Toda chave escrita pelo app começa com este prefixo. */
export const PREFIXO = 'financas:';
export const CHAVE_ESTADO = `${PREFIXO}estado`;
export const SCHEMA_ATUAL = 2;

export function estadoInicial(): AppState {
  return {
    schemaVersion: SCHEMA_ATUAL,
    contas: [],
    categorias: categoriasPadrao(),
    transacoes: [],
    orcamentos: [],
    metas: [],
    recorrencias: [],
    mapeamentosCsv: {},
    importacoes: [],
    pagamentosFatura: [],
    agenda: [],
    regras: [],
    investimentos: [],
    dividas: [],
  };
}

export type Carga =
  | { tipo: 'ok'; estado: AppState }
  | { tipo: 'corrompido'; bruto: string }
  | { tipo: 'versao-futura'; bruto: string; versao: number };

type Dados = Record<string, unknown>;

/** Migrações indexadas pela versão de origem: `migracoes[n]` leva de n para n+1. */
const migracoes: Record<number, (dados: Dados) => Dados> = {
  0: (dados) => ({
    ...dados,
    schemaVersion: 1,
    contas: dados.contas ?? [],
    categorias: dados.categorias ?? categoriasPadrao(),
    transacoes: dados.transacoes ?? [],
    orcamentos: dados.orcamentos ?? [],
    metas: dados.metas ?? [],
    recorrencias: dados.recorrencias ?? [],
    mapeamentosCsv: dados.mapeamentosCsv ?? {},
    importacoes: dados.importacoes ?? [],
  }),
  // v2: pagamentos de fatura de cartão.
  1: (dados) => ({ ...dados, schemaVersion: 2, pagamentosFatura: dados.pagamentosFatura ?? [] }),
};

const CHAVES_LISTA = ['contas', 'categorias', 'transacoes', 'orcamentos', 'metas', 'recorrencias', 'importacoes', 'pagamentosFatura'] as const;

function ehObjeto(x: unknown): x is Dados {
  return typeof x === 'object' && x !== null && !Array.isArray(x);
}

function estruturaValida(dados: Dados): boolean {
  return (
    CHAVES_LISTA.every((k) => Array.isArray(dados[k])) &&
    ehObjeto(dados.mapeamentosCsv) &&
    dados.schemaVersion === SCHEMA_ATUAL
  );
}

/** Migra um objeto qualquer até a versão atual. Versões futuras são recusadas. */
export function migrar(bruto: unknown): { tipo: 'ok'; estado: AppState } | { tipo: 'corrompido' } | { tipo: 'versao-futura'; versao: number } {
  if (!ehObjeto(bruto)) return { tipo: 'corrompido' };
  let dados: Dados = bruto;
  const versaoLida = dados.schemaVersion === undefined ? 0 : dados.schemaVersion;
  if (typeof versaoLida !== 'number' || !Number.isInteger(versaoLida) || versaoLida < 0) {
    return { tipo: 'corrompido' };
  }
  if (versaoLida > SCHEMA_ATUAL) return { tipo: 'versao-futura', versao: versaoLida };
  if (versaoLida === 0 && !CHAVES_LISTA.some((k) => k in dados)) return { tipo: 'corrompido' };
  for (let v = versaoLida; v < SCHEMA_ATUAL; v++) {
    const migracao = migracoes[v];
    if (!migracao) return { tipo: 'corrompido' };
    dados = migracao(dados);
  }
  // Chaves aditivas (novos módulos) ausentes em dados antigos recebem o valor inicial, sem migração.
  const padrao = estadoInicial() as unknown as Dados;
  for (const chave of Object.keys(padrao)) if (dados[chave] === undefined) dados = { ...dados, [chave]: padrao[chave] };
  if (!estruturaValida(dados)) return { tipo: 'corrompido' };
  return { tipo: 'ok', estado: dados as unknown as AppState };
}

export function carregar(storage: Storage): Carga {
  let bruto: string | null;
  try {
    bruto = storage.getItem(CHAVE_ESTADO);
  } catch {
    return { tipo: 'ok', estado: estadoInicial() };
  }
  if (bruto === null) return { tipo: 'ok', estado: estadoInicial() };
  let parsed: unknown;
  try {
    parsed = JSON.parse(bruto);
  } catch {
    return { tipo: 'corrompido', bruto };
  }
  const r = migrar(parsed);
  if (r.tipo === 'ok') return r;
  if (r.tipo === 'versao-futura') return { tipo: 'versao-futura', bruto, versao: r.versao };
  return { tipo: 'corrompido', bruto };
}

/** Lança se o navegador recusar a gravação (cota excedida, armazenamento bloqueado). */
export function salvar(estado: AppState, storage: Storage): void {
  storage.setItem(CHAVE_ESTADO, JSON.stringify(estado));
}

export function apagarTudo(storage: Storage): void {
  const chaves: string[] = [];
  for (let i = 0; i < storage.length; i++) {
    const chave = storage.key(i);
    if (chave?.startsWith(PREFIXO)) chaves.push(chave);
  }
  chaves.forEach((c) => storage.removeItem(c));
}

export function exportarJson(estado: AppState): string {
  return JSON.stringify(estado, null, 2);
}

/** Lê um arquivo de exportação, migrando se necessário. */
export function importarJson(texto: string): Resultado<AppState> {
  let parsed: unknown;
  try {
    parsed = JSON.parse(texto);
  } catch {
    return falha('O arquivo não é um JSON válido.');
  }
  const r = migrar(parsed);
  if (r.tipo === 'ok') return ok(r.estado);
  if (r.tipo === 'versao-futura') {
    return falha(`O arquivo foi gerado por uma versão mais nova do app (esquema ${r.versao}).`);
  }
  return falha('O arquivo não parece ser uma exportação deste app.');
}
import { BrowserRouter, Navigate, Route, Routes } from 'react-router-dom';
import { FalhaCarregamento } from './components/FalhaCarregamento';
import { Layout } from './components/Layout';
import { DashboardPage } from './pages/DashboardPage';
import { CalendarioPage } from './pages/CalendarioPage';
import { CartoesPage } from './pages/CartoesPage';
import { ContasPage } from './pages/ContasPage';
import { ConfiguracoesPage } from './pages/ConfiguracoesPage';
import { DividasPage } from './pages/DividasPage';
import { ImportarCsvPage } from './pages/ImportarCsvPage';
import { InvestimentosPage } from './pages/InvestimentosPage';
import { MetasPage } from './pages/MetasPage';
import { AjudaPage } from './pages/AjudaPage';
import { OrcamentoPage } from './pages/OrcamentoPage';
import { RelatoriosPage } from './pages/RelatoriosPage';
import { RegrasPage } from './pages/RegrasPage';
import { TransacoesPage } from './pages/TransacoesPage';
import { useSnapshot } from './state/store';

/** Rotas do app; separadas do roteador para poderem ser testadas com MemoryRouter. */
export function AppRoutes() {
  const { problema } = useSnapshot();
  if (problema) return <FalhaCarregamento problema={problema} />;
  return (
    <Routes>
      <Route element={<Layout />}>
        <Route index element={<DashboardPage />} />
